def compute(vars):
    total_operating_expenses = vars["v1"]
    net_interest_revenue = vars["v2"]

    if net_interest_revenue == 0:
        return None

    ratio = total_operating_expenses / net_interest_revenue
    percentage = ratio * 100

    return {
        "value": percentage,
        "trace": {
            "total_operating_expenses": total_operating_expenses,
            "net_interest_revenue": net_interest_revenue,
            "ratio": ratio,
            "percentage": percentage,
            "output_meta": {
                "currency": "USD",
                "scale": "million",
                "unit": "percent"
            }
        }
    }
